// Generated by `dart run drift_dev make-migrations`, then filled in.
import 'package:doxa_pdf/features/library/library_database.dart';
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';

import 'generated/schema.dart';

import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v2.dart' as v2;

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // These simple tests verify all possible schema updates with a simple (no
    // data) migration. This is a quick way to ensure that written database
    // migrations properly alter the schema.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = LibraryDatabase(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  // Users upgrading must keep their recents, favorites and reading state.
  test('migration from v1 to v2 keeps every document', () async {
    // Schema snapshots use SQLite's storage: booleans are 0/1 and dates
    // are seconds since the epoch.
    final opened = DateTime.utc(2026, 11, 26, 9).millisecondsSinceEpoch ~/ 1000;
    final oldDocuments = [
      v1.DocumentsData(
        id: 1,
        identity: 'v1-a',
        uri: 'content://provider/1',
        displayName: 'Calculus.pdf',
        pageCount: 504,
        page: 311,
        pageX: 0.25,
        pageY: 0.5,
        zoom: 1.5,
        rightToLeft: 0,
        favorite: 1,
        inRecents: 1,
        lastOpenedAt: opened,
      ),
      v1.DocumentsData(
        id: 2,
        identity: 'v1-b',
        uri: null,
        displayName: 'Shared.pdf',
        pageCount: 0,
        page: 0,
        pageX: 0,
        pageY: 0,
        zoom: 1,
        rightToLeft: 1,
        favorite: 0,
        inRecents: 0,
        lastOpenedAt: opened,
      ),
    ];
    final expected = [
      for (final d in oldDocuments) v2.DocumentsData.fromJson(d.toJson()),
    ];

    await verifier.testWithDataIntegrity(
      oldVersion: 1,
      newVersion: 2,
      createOld: v1.DatabaseAtV1.new,
      createNew: v2.DatabaseAtV2.new,
      openTestedDatabase: LibraryDatabase.new,
      createItems: (batch, oldDb) =>
          batch.insertAll(oldDb.documents, oldDocuments),
      validateItems: (newDb) async {
        expect(await newDb.select(newDb.documents).get(), expected);
      },
    );
  });
}
